// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.llamacpp/** * NOUS — llama.cpp JNI Bridge (v2.1). * * Kotlin-side JNI declarations for llama.cpp native library. * The C++ implementation lives in `src/main/cpp/jarvis_llm.cpp`. * * ## v2.1 Features *   - mmap memory mapping (prevents OOM for large models) *   - Async-signal-safe crash handler (pipe + watchdog) *   - Zero-copy token streaming (token IDs, NOT strings) *   - Barge-in via `g_should_stop` atomic flag *   - KV cache context shifting *   - Lookahead decoding (no draft model) *   - LoRA adapter hot-swapping * * ## Native Library Loading * * The library is loaded lazily on first use. If the library is not found * (e.g., dev build without pre-built .so), all methods throw * `UnsatisfiedLinkError` — caught by [LlamaCppProvider] which returns * a graceful error. * * @see <a href="docs/strategy/module-4-strategy-v2.1.md">§4 Local LLM</a> */object LlamaCppJni {    @Volatile    private var loaded: Boolean = false    @Volatile    private var loadFailed: Boolean = false    /**     * Load the native library. Safe to call multiple times.     *     * @return true if loaded successfully, false if library not available     */    @Synchronized    fun ensureLoaded(): Boolean {        if (loaded) return true        if (loadFailed) return false        return try {            System.loadLibrary("jarvis_llm")            loaded = true            true        } catch (e: UnsatisfiedLinkError) {            // Library not available (dev build without pre-built .so)            loadFailed = true            false        } catch (e: SecurityException) {            loadFailed = true            false        }    }    /** Whether the native library is loaded. */    val isLoaded: Boolean get() = loaded    // ─── Model lifecycle ──────────────────────────────────────────    /**     * Load a GGUF model file into memory.     *     * @param modelPath absolute path to .gguf file     * @param contextLength max context window in tokens     * @param useGpu offload layers to Vulkan GPU     * @param useMmap use memory-mapped file I/O (v2.1 — prevents OOM)     * @return model handle (>0 = success, 0 = failure)     */    fun nativeLoadModel(        modelPath: String,        contextLength: Int,        useGpu: Boolean,        useMmap: Boolean,    ): Long {        if (!ensureLoaded()) return 0L        return nativeLoadModelImpl(modelPath, contextLength, useGpu, useMmap)    }    /**     * Unload a model and free native memory.     *     * Safe to call multiple times — second call is a no-op.     */    fun nativeUnload(modelHandle: Long) {        if (!ensureLoaded() || modelHandle == 0L) return        nativeUnloadImpl(modelHandle)    }    // ─── Generation ───────────────────────────────────────────────    /**     * Generate text with streaming token callback.     *     * v2.1: Passes token IDs (jint) via callback — zero JNI string allocation.     * Kotlin side decodes token IDs to strings using local vocabulary.     *     * @param modelHandle loaded model handle     * @param prompt full prompt text     * @param maxTokens max tokens to generate     * @param temperature sampling temperature (0.0-2.0)     * @param topP nucleus sampling threshold (0.0-1.0)     * @param topK top-K sampling (1-100)     * @param repeatPenalty repetition penalty (0.5-2.0)     * @param callback receives token IDs + shouldStop() check     * @return full generated text     */    fun nativeGenerate(        modelHandle: Long,        prompt: String,        maxTokens: Int,        temperature: Float,        topP: Float,        topK: Int,        repeatPenalty: Float,        callback: TokenCallback,    ): String {        if (!ensureLoaded() || modelHandle == 0L) return ""        return nativeGenerateImpl(            modelHandle, prompt, maxTokens, temperature, topP, topK, repeatPenalty, callback        )    }    /**     * Stop generation immediately (v2.1 barge-in at C++ level).     *     * Sets `g_should_stop` atomic flag — C++ loop checks every token.     * Stops within 1 token (< 50ms).     */    fun nativeStopGeneration() {        if (!ensureLoaded()) return        nativeStopGenerationImpl()    }    // ─── Embedding ────────────────────────────────────────────────    /**     * Generate embedding for text.     *     * @return float array (dimension depends on model)     */    fun nativeEmbed(modelHandle: Long, text: String): FloatArray {        if (!ensureLoaded() || modelHandle == 0L) return FloatArray(0)        return nativeEmbedImpl(modelHandle, text)    }    // ─── Vulkan ───────────────────────────────────────────────────    /** Check if Vulkan GPU is available. */    fun nativeHasVulkan(): Boolean {        if (!ensureLoaded()) return false        return nativeHasVulkanImpl()    }    /**     * Check if Vulkan context is still valid (v2.1 context loss handling).     *     * Android destroys GPU context when app goes to deep background.     * This checks if the context survived.     */    fun nativeCheckVulkanContext(modelHandle: Long): Boolean {        if (!ensureLoaded() || modelHandle == 0L) return false        return nativeCheckVulkanContextImpl(modelHandle)    }    // ─── KV Cache ─────────────────────────────────────────────────    /**     * Check context overflow and shift if needed (v2.1 context shifting).     *     * If KV cache is > 80% full, removes oldest 30% of tokens.     * This enables infinite conversations without model reload.     */    fun nativeCheckContextOverflow(modelHandle: Long, contextLength: Int) {        if (!ensureLoaded() || modelHandle == 0L) return        nativeCheckContextOverflowImpl(modelHandle, contextLength)    }    // ─── LoRA ─────────────────────────────────────────────────────    /**     * Load a LoRA adapter on top of base model (v2.1 persona hot-swap).     *     * @param loraPath path to .gguf LoRA file (~20MB)     * @param scale LoRA scale factor (1.0 = full strength)     * @return LoRA handle (>0 = success, 0 = failure)     */    fun nativeLoadLoraAdapter(        modelHandle: Long,        loraPath: String,        scale: Float,    ): Long {        if (!ensureLoaded() || modelHandle == 0L) return 0L        return nativeLoadLoraAdapterImpl(modelHandle, loraPath, scale)    }    /**     * Remove a LoRA adapter.     */    fun nativeRemoveLoraAdapter(modelHandle: Long, loraHandle: Long) {        if (!ensureLoaded() || modelHandle == 0L || loraHandle == 0L) return        nativeRemoveLoraAdapterImpl(modelHandle, loraHandle)    }    // ─── Crash Handler ────────────────────────────────────────────    /**     * Install async-signal-safe crash handler (v2.1).     *     * Writes signal code to pipe fd on SIGSEGV/SIGABRT.     * A separate watchdog process reads the pipe and handles recovery.     *     * @param pipeFd write end of pipe (created by watchdog process)     */    fun installCrashHandler(pipeFd: Int) {        if (!ensureLoaded()) return        nativeInstallCrashHandler(pipeFd)    }    // ─── Vocabulary ───────────────────────────────────────────────    /**     * Get vocabulary size (number of tokens).     */    fun nativeGetVocabSize(modelHandle: Long): Int {        if (!ensureLoaded() || modelHandle == 0L) return 0        return nativeGetVocabSizeImpl(modelHandle)    }    /**     * Get token text for a token ID (loaded once at model load).     */    fun nativeGetTokenText(modelHandle: Long, tokenId: Int): String? {        if (!ensureLoaded() || modelHandle == 0L) return null        return nativeGetTokenTextImpl(modelHandle, tokenId)    }    // ─── Callback interface ───────────────────────────────────────    /**     * Token callback (v2.1: zero-copy).     *     * Receives token IDs (int) — Kotlin decodes to string using vocabulary.     * No JNI string allocation = no GC pressure.     */    interface TokenCallback {        /** Called for each generated token (v2.1: token ID, NOT string). */        fun onTokenId(tokenId: Int)        /** Check if generation should stop (barge-in). */        fun shouldStop(): Boolean    }    // ─── Native method declarations (private) ─────────────────────    private external fun nativeLoadModelImpl(        modelPath: String,        contextLength: Int,        useGpu: Boolean,        useMmap: Boolean,    ): Long    private external fun nativeUnloadImpl(modelHandle: Long)    private external fun nativeGenerateImpl(        modelHandle: Long,        prompt: String,        maxTokens: Int,        temperature: Float,        topP: Float,        topK: Int,        repeatPenalty: Float,        callback: TokenCallback,    ): String    private external fun nativeStopGenerationImpl()    private external fun nativeEmbedImpl(modelHandle: Long, text: String): FloatArray    private external fun nativeHasVulkanImpl(): Boolean    private external fun nativeCheckVulkanContextImpl(modelHandle: Long): Boolean    private external fun nativeCheckContextOverflowImpl(modelHandle: Long, contextLength: Int)    private external fun nativeLoadLoraAdapterImpl(        modelHandle: Long,        loraPath: String,        scale: Float,    ): Long    private external fun nativeRemoveLoraAdapterImpl(modelHandle: Long, loraHandle: Long)    private external fun nativeInstallCrashHandler(pipeFd: Int)    private external fun nativeGetVocabSizeImpl(modelHandle: Long): Int    private external fun nativeGetTokenTextImpl(modelHandle: Long, tokenId: Int): String?}